edge_getattr.source:
# Edge: __getattr__ / __setattr__ / __delattr__

class Proxy:
    def __init__(self):
        self._data = {}

    def __getattr__(self, name):
        if name.startswith("_"):
            raise AttributeError(name)
        return self._data.get(name, "N/A")

    def __setattr__(self, name, value):
        if name.startswith("_"):
            object.__setattr__(self, name, value)
        else:
            self._data[name] = value

    def __delattr__(self, name):
        if name.startswith("_"):
            object.__delattr__(self, name)
        elif name in self._data:
            del self._data[name]

p = Proxy()
p.foo = 42
p.bar = "hello"
print(p.foo)                 # 42
print(p.bar)                 # hello
print(p.baz)                 # N/A (default from __getattr__)

del p.foo
print(p.foo)                 # N/A (已删除)

print("done")

edge_hash.source:
# Edge: __hash__ 和 hashable

# 内置类型的 hash
print(type(hash(42)))        # <class 'int'>
print(type(hash("hello")))   # <class 'int'>
print(type(hash(3.14)))      # <class 'int'>
print(type(hash(True)))      # <class 'int'>

# 相同值有相同 hash
print(hash(42) == hash(42))  # True

# list 不可 hash
try:
    hash([1, 2, 3])
except TypeError:
    print("TypeError")       # TypeError

# dict 不可 hash
try:
    hash({"a": 1})
except TypeError:
    print("TypeError")       # TypeError

# 自定义 __hash__
class Hashable:
    def __init__(self, v):
        self.v = v
    def __hash__(self):
        return hash(self.v)
    def __eq__(self, other):
        if isinstance(other, Hashable):
            return self.v == other.v
        return NotImplemented

h1 = Hashable(42)
h2 = Hashable(42)
print(hash(h1) == hash(h2))  # True

print("done")

