edge_property.source:
# Edge: @property 装饰器

class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("radius must be non-negative")
        self._radius = value

    @property
    def area(self):
        return 3.14159 * self._radius * self._radius

c = Circle(5)
print(c.radius)              # 5
print(c.area)                # ~78.53975

c.radius = 10
print(c.radius)              # 10
print(c.area)                # ~314.159

# @property 只读
class ReadOnly:
    def __init__(self, v):
        self._v = v

    @property
    def v(self):
        return self._v

ro = ReadOnly(42)
print(ro.v)                  # 42
try:
    ro.v = 100
except AttributeError:
    print("AttributeError")  # AttributeError

print("done")

edge_protocols.source:
# Edge: __len__ / __contains__ / __iter__ / __next__

# __len__
class MyCollection:
    def __init__(self, items):
        self.items = items
    def __len__(self):
        return len(self.items)
    def __contains__(self, item):
        return item in self.items
    def __iter__(self):
        return iter(self.items)

mc = MyCollection([1, 2, 3, 4, 5])
print(len(mc))               # 5
print(3 in mc)               # True
print(6 in mc)               # False

for item in mc:
    print(item, end=" ")     # 1 2 3 4 5
print()

# 转列表
print(list(mc))              # [1, 2, 3, 4, 5]

print("done")

edge_recursion.source:
# Edge: 递归深度

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

print(factorial(5))           # 120
print(factorial(10))          # 3628800

# 相互递归
def is_even(n):
    if n == 0:
        return True
    return is_odd(n - 1)

def is_odd(n):
    if n == 0:
        return False
    return is_even(n - 1)

print(is_even(10))            # True
print(is_even(11))            # False
print(is_odd(10))             # False
print(is_odd(11))             # True

print("done")

edge_yield_closure.source:
# 生成器与闭包 / 默认参数 / 类方法

# 闭包变量跨 yield 可见
def make(limit):
    def gen():
        i = 0
        while i < limit:
            yield i
            i += 1
    return gen
print(list(make(3)()))      # [0, 1, 2]

# 默认参数 / 位置参数
def with_default(start=0, step=1):
    n = start
    while n < 3:
        yield n
        n += step
print(list(with_default(1)))        # [1, 2]
print(list(with_default(0, 2)))     # [0, 2]

# 类方法 (self 绑定)
class C:
    def __init__(self, name):
        self.name = name
    def gen(self):
        yield self.name
        yield self.name.upper()
c = C("py")
print(list(c.gen()))        # ['py', 'PY']

# 嵌套生成器各自独立挂起状态
def a():
    for i in range(2):
        yield ("a", i)
def b():
    for i in range(2):
        yield ("b", i)
ia, ib = a(), b()
print(list(zip(ia, ib)))    # [(('a', 0), ('b', 0)), (('a', 1), ('b', 1))]

print("done")

edge_yield_controlflow.source:
# 生成器与控制流结构测试 (if/while/for/try/break/continue/else)

# yield 在 if/else 中
def gif(flag):
    if flag:
        yield "yes"
    else:
        yield "no"
print(list(gif(True)))      # ['yes']
print(list(gif(False)))     # ['no']

# yield 在 while 中 (含 break/continue)
def gwhile():
    i = 0
    while True:
        i += 1
        if i == 2:
            continue
        yield i
        if i >= 4:
            break
print(list(gwhile()))       # [1, 3, 4]

# yield 在 for 中 (含 for-else: break 时 else 不执行)
def gfor():
    for i in range(3):
        yield i
        if i == 1:
            break
    else:
        yield "no-break"
print(list(gfor()))         # [0, 1]

def gfor2():
    for i in range(3):
        yield i
    else:
        yield "no-break"
print(list(gfor2()))        # [0, 1, 2, 'no-break']

# yield 在 while-else 中
def gwhile_else():
    i = 0
    while i < 2:
        yield i
        i += 1
    else:
        yield "while-done"
print(list(gwhile_else()))  # [0, 1, 'while-done']

# yield 在 try/except/finally 中
def gtry():
    try:
        yield 1
        yield 2
    finally:
        yield "finally"
print(list(gtry()))         # [1, 2, 'finally']

# yield from 在循环中
def inner():
    yield "a"
    yield "b"
def gouter():
    for i in range(2):
        yield i
        yield from inner()
print(list(gouter()))       # [0, 'a', 'b', 1, 'a', 'b']

print("done")

