# dict 合并运算符 | 与 ** 解包测试 (Python 3.9+)

# 基础合并
d1 = {"a": 1, "b": 2}
d2 = {"b": 3, "c": 4}
print(d1 | d2)              # {'a': 1, 'b': 3, 'c': 4} (右侧覆盖左侧同键)

# |= 增强赋值 (原地合并)
d3 = {"a": 1}
d3 |= d2
print(d3)                   # {'a': 1, 'b': 3, 'c': 4}

# 合并不改变原字典
