# random 抽样函数的参数类型规则 (与 CPython 一致)
# 随机数值序列不同, 故此处只断言错误类型/文案与结构性结果

import random
import time

random.seed(11)


def gen():
    yield 1
    yield 2
    yield 3


# 抽样函数需要序列 (内部取 len), 生成器一律被拒绝
try:
    random.choice(gen())
except TypeError as e:
    print("choice TypeError:", e)

try:
    random.choices(gen(), k=2)
except TypeError as e:
    print("choices TypeError:", e)

try:
    random.sample(gen(), 2)
except TypeError as e:
    print("sample TypeError:", e)

try:
    random.shuffle(gen())
except TypeError as e:
    print("shuffle TypeError:", e)

# 生成器表达式同样被拒绝
try:
    random.choices(x for x in range(3))
except TypeError as e:
    print("genexpr TypeError:", e)

# 集合不可下标, 故 choice 拒绝; sample 认为它不是序列
try:
    random.choice({1, 2, 3})
except TypeError as e:
    print("choice(set):", e)

try:
    random.sample({1, 2, 3}, 2)
except TypeError as e:
    print("sample(set):", e)

try:
    random.sample({"a": 1}, 1)
except TypeError as e:
    print("sample(dict):", e)

# shuffle 需要可写序列: 元组/字符串/range 不支持元素赋值
try:
    random.shuffle((1, 2, 3))
except TypeError as e:
    print("shuffle(tuple):", e)

try:
    random.shuffle("abc")
except TypeError as e:
    print("shuffle(str):", e)

try:
    random.shuffle(range(3))
except TypeError as e:
    print("shuffle(range):", e)

# choice 支持字符串与 range
print("choice(str) ok:", random.choice("abc") in "abc")
print("choice(range) ok:", random.choice(range(5)) in range(5))

# weights 只需可迭代, 生成器可接受 (CPython 不做 len 检查)
print("weights ok:", len(random.choices([1, 2, 3], weights=(1 for _ in range(3)), k=4)))


# weights 为含 sleep 的生成器: 消费中途挂起须重放, 不能拿半截权重去比对
def sleep_weights():
    n = 0
    while n < 3:
        time.sleep(0)
        n += 1
        yield 1


print("weights sleep:", len(random.choices([1, 2, 3], weights=sleep_weights(), k=4)))

# 序列参数正常支持 (仅结构性断言)
print(len(random.choices([1, 2, 3], k=5)))
print(len(random.sample(range(10), 3)))
print(sorted(random.sample("abcd", 4)) == ["a", "b", "c", "d"])
lst = [1, 2, 3]
random.shuffle(lst)
print(sorted(lst) == [1, 2, 3])
d = {0: "zero", 1: "one", 2: "two"}
random.shuffle(d)
print(len(d), d[0] in ["zero", "one", "two"])

print("done")

lang_sleep_nested.source:
# 嵌套生成器内的 sleep 测试 (与 CPython 行为一致)

import time
import operator

# 生成器体内迭代另一个含 sleep 的生成器
def inner():
    for i in range(2):
        time.sleep(0)
        yield i


def outer():
    for x in inner():
        yield x * 10


print(list(outer()))

# 三层嵌套: c() -> b() -> a(), a 内 sleep
def la():
    for i in range(2):
        time.sleep(0)
        yield i


def lb():
    for x in la():
        yield x + 1


def lc():
    for y in lb():
        yield y * 10


print(list(lc()))

# yield from 嵌套
def yf_outer():
    yield from la()


print(list(yf_outer()))

# 生成器内 genexpr + sleep
def ge_outer():
    for v in (x * 2 for x in la()):
        yield v


print(list(ge_outer()))

# 嵌套 + 消费函数
def cb():
    for x in la():
        yield x + 1


print(sum(cb()))
print(sorted(cb()))

# 嵌套 + 嵌套消费
def nb():
    for x in la():
        yield x * 10


print([[y for y in nb()] for _ in range(2)])

# 嵌套 + send: yield from 后继续产出
def sd_outer():
    v = yield from la()
    yield 'got'


print(list(sd_outer()))

# 嵌套 + 闭包: 生成器工厂
def make(n):
    def gen():
        for i in range(n):
            time.sleep(0)
            yield i * 2
    return gen()


def consume(g):
    for x in g:
        yield x


print(list(consume(make(2))))

# 消费点: next() / operator.indexOf() / 字面量 * 解包
def ng():
    time.sleep(0)
    yield 1
    time.sleep(0)
    yield 2


it = ng()
print(next(it))
print(next(it))


def ig():
    for i in [5, 6, 7]:
        time.sleep(0)
        yield i


print(operator.indexOf(ig(), 6))


def sg():
    for i in range(3):
        time.sleep(0)
        yield i


print([*sg()])
print([*sg(), 99])
print((*sg(),))

# 生成器内 sleep 后抛异常 (异常穿过嵌套生成器传播)
def eg():
    time.sleep(0)
    yield 1
    time.sleep(0)
    raise ValueError("mid")


def ec():
    for x in eg():
        yield x


eit = ec()
try:
    print(next(eit))
    next(eit)
except ValueError as e:
    print("caught:", e)

# 异常在 for 循环的最后一条语句处抛出, 也须外传给外层 try
def fg():
    time.sleep(0)
    yield 1
    raise ValueError("late")


try:
    for v in fg():
        print("v:", v)
except ValueError as e:
    print("caught:", e)

# 同上, 但不含 sleep (验证挂起与异常两条传播路径相互独立)
def ng2():
    yield 1
    raise ValueError("boom")


try:
    for v in ng2():
        print("v:", v)
except ValueError as e:
    print("caught:", e)

print("done")

lang_super.source:
# super() 支持测试

# 基本继承: super() 调用父类方法
class Animal:
    def __init__(self, name):
        self.name = name

    def speak(self):
        return self.name + " makes a sound"

class Dog(Animal):
    def __init__(self, name):
        super().__init__(name)

    def speak(self):
        return super().speak() + " (from Dog)"

d = Dog("Buddy")
print(d.speak())           # Buddy makes a sound (from Dog)

# 多层继承链
class A:
    def val(self):
        return 1

class B(A):
    def val(self):
        return super().val() + 10

class C(B):
    def val(self):
        return super().val() + 100

print(C().val())           # 111

# super() 与属性访问
class Base:
    def __init__(self):
        self.x = 10

    def get_x(self):
        return self.x

class Sub(Base):
    def get_x(self):
        return super().get_x() * 2

s = Sub()
print(s.get_x())           # 20

# 双参数 super(Class, obj)
class P:
    def greet(self):
        return "parent"

class Q(P):
    def greet(self):
        return "child"

q = Q()
print(super(Q, q).greet()) # parent

# super() 与运算符重载结合
class Num:
    def __init__(self, v):
        self.v = v

    def value(self):
        return self.v

class BetterNum(Num):
    def value(self):
        return super().value() + 1000

n = BetterNum(5)
print(n.value())           # 1005

print("done")

